command:
cd /app && python3 - <<'PYEOF'
path = 'tests/tests.rs'
s = open(path).read()

# test_sort_natural: append symlink
old = """        "file2.txt
        file7.txt
        file007.txt
        file9.txt
        file10.txt
        file20.txt",
    );
}"""
new = """        "file2.txt
        file7.txt
        file007.txt
        file9.txt
        file10.txt
        file20.txt
        symlink",
    );
}"""
assert old in s
s = s.replace(old, new)

# test_sort_natural_case_sensitive: append symlink
old = """        "File2.txt
        file2.txt
        file10.txt",
    );
}"""
new = """        "File2.txt
        file2.txt
        file10.txt
        symlink",
    );
}"""
assert old in s
s = s.replace(old, new)

# test_sort_reverse: symlink first
old = """        "c.txt
        b.txt
        a.txt",
    );
}"""
new = """        "symlink
        c.txt
        b.txt
        a.txt",
    );
}"""
assert old in s
s = s.replace(old, new)

# test_sort_multi_key: symlink before z
old = """        "z
        a.foo
        b.foo
        a.txt
        b.txt
        c.txt",
    );
}"""
new = """        "symlink
        z
        a.foo
        b.foo
        a.txt
        b.txt
        c.txt",
    );
}"""
assert old in s
s = s.replace(old, new)

# test_sort_missing_last: symlink before z
old = """        "a.txt
        b.foo
        z",
    );
}"""
new = """        "a.txt
        b.foo
        symlink
        z",
    );
}"""
assert old in s
s = s.replace(old, new)

# test_sort_max_results_after_sort: reverse expected symlink first
old = """        "e.txt
        d.txt
        c.txt",
    );
}"""
new = """        "symlink
        e.txt
        d.txt",
    );
}"""
assert old in s
s = s.replace(old, new)

# test_sort_requires_sort expected
old = """    te.assert_failure_with_error(&["--reverse", "."], "required arguments were not provided");"""
new = """    te.assert_failure_with_error(&["--reverse", "."], "error: the following required arguments were not provided");"""
assert old in s
s = s.replace(old, new)

# test_sort_seed_requires_sort expected
old = """    te.assert_failure_with_error(&["--sort-seed", "1", "."], "required arguments were not provided");"""
new = """    te.assert_failure_with_error(&["--sort-seed", "1", "."], "error: the following required arguments were not provided");"""
assert old in s
s = s.replace(old, new)

open(path, 'w').write(s)
print("OK")
PYEOF
